+import { $internal } from '../common';
+import { isRelation } from '../relation/utils/is-relation';
+import type { Schema } from '../storage';
+import type { Trait, TraitRecord, TraitValue } from '../trait/types';
+
+let aspectId = 0;
+
+export type Aspect<TTraits extends readonly Trait[] = readonly Trait[]> = {
+    readonly id: number;
+    readonly traits: TTraits;
+    readonly schema: Schema;
+    [$internal]: { fields: Map<string, Trait> };
+};
+
+export type AspectRecord<T extends Aspect> = UnionToIntersection<TraitRecord<T['traits'][number]>>;
+export type AspectValue<T extends Aspect> = Partial<AspectRecord<T>>;
+
+type UnionToIntersection<T> = (T extends unknown ? (value: T) => void : never) extends (
+    value: infer U
+) => void
+    ? U
+    : never;
+
+export function isAspect(value: unknown): value is Aspect {
+    return Boolean((value as Aspect | undefined)?.[$internal]?.fields);
+}
+
+export function createAspect<T extends readonly [Trait, Trait, ...Trait[]]>(
+    ...inputs: T
+): Aspect<T> {
+    const traits: Trait[] = [];
+    const fields = new Map<string, Trait>();
+
+    for (const input of inputs) {
+        if (isRelation(input)) throw new Error('Aspects cannot contain relations');
+        const members = isAspect(input) ? input.traits : [input];
+        for (const trait of members) {
+            if (trait[$internal].relation) throw new Error('Aspects cannot contain relations');
+            traits.push(trait);
+            if (typeof trait.schema === 'function') {
+                throw new Error('Aspects cannot contain AoS traits');
+            }
+            for (const field of Object.keys(trait.schema)) {
+                if (fields.has(field)) {
+                    throw new Error(`Aspect field "${field}" is defined by more than one trait`);
+                }
+                fields.set(field, trait);
+            }
+        }
+    }
+
+    const schema = Object.assign({}, ...traits.map((trait) => trait.schema));
+    const id = aspectId++;
+    return Object.freeze({ id, traits: Object.freeze(traits), schema: Object.freeze(schema), [$internal]: { fields } }) as Aspect<T>;
+}
+
+export function getAspectValue(entity: { get(trait: Trait): any }, aspect: Aspect) {
+    const value: Record<string, unknown> = {};
+    for (const trait of aspect.traits) {
+        const data = entity.get(trait);
+        if (data === undefined) return undefined;
+        Object.assign(value, data);
+    }
+    return value;
+}
+
+export function aspectValues(aspect: Aspect, value: Record<string, unknown> | undefined) {
+    const values = new Map<Trait, Record<string, unknown>>();
+    if (!value) return values;
+    for (const [field, fieldValue] of Object.entries(value)) {
+        const trait = aspect[$internal].fields.get(field);
+        if (!trait) continue;
+        let target = values.get(trait);
+        if (!target) values.set(trait, (target = {}));
+        target[field] = fieldValue;
+    }
+    return values;
+}
