+function createAspectQueryResult(
+    world: World,
+    entities: Entity[],
+    query: QueryInstance,
+    params: QueryParameter[]
+) {
+    const results = Object.assign(entities, {
+        readEach(callback: any) {
+            for (let i = 0; i < entities.length; i++) callback(readAspectState(entities[i], params), entities[i], i);
+            return results;
+        },
+        updateEach(callback: any, options: QueryResultOptions = { changeDetection: 'auto' }) {
+            for (let i = 0; i < entities.length; i++) {
+                const entity = entities[i];
+                const state = readAspectState(entity, params);
+                callback(state, entity, i);
+                if (!world.has(entity)) continue;
+                for (let j = 0; j < params.length; j++) {
+                    const parameter = params[j];
+                    if (isAspect(parameter)) {
+                        for (const [trait, value] of aspectValues(parameter, state[j]).entries()) {
+                            entity.set(trait, value, options.changeDetection !== 'never');
+                        }
+                    }
+                }
+            }
+            return results;
+        },
+        useStores(callback: any) { callback([], entities); return results; },
+        select(...selected: QueryParameter[]) { params = selected; return results; },
+        sort(callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)) {
+            Array.prototype.sort.call(entities, callback); return results;
+        },
+    });
+    return results;
+}
+
+function readAspectState(entity: Entity, params: QueryParameter[]) {
+    const state: any[] = [];
+    for (const parameter of params) {
+        if (isAspect(parameter)) state.push(getAspectValue(entity, parameter));
+        else if (!isModifier(parameter) && !isRelationPair(parameter) && parameter[$internal].type !== 'tag') state.push(entity.get(parameter));
+    }
+    return state;
+}
